const express = require('express');
const Pool = require('pg-pool');

const app = express();

const tenantMigrationPools = new Map();

function getMigrationPool(tenantId) {
  if (!tenantMigrationPools.has(tenantId)) {
    tenantMigrationPools.set(
      tenantId,
      new Pool({
        database: `tenant_schema_${tenantId}`,
        host: 'db-migrations.internal',
        user: 'migration_monitor',
        password: process.env.MIGRATION_DB_PASSWORD
      })
    );
  }
  return tenantMigrationPools.get(tenantId);
}

app.get('/api/tenants/:tenantId/schema/status', async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const { tenantId } = req.params;

  // Verify that the caller belongs to the tenant and has developer or admin privileges
  if (req.user.tenantId !== tenantId) {
    return res.status(403).json({ error: 'Access denied: cannot inspect schema status of another tenant' });
  }

  if (!req.user.isAdmin && !req.user.isDeveloper) {
    return res.status(403).json({ error: 'Access denied: administrative or developer privilege required' });
  }

  const pool = getMigrationPool(tenantId);

  try {
    const { rows } = await pool.query(
      'SELECT version, name, applied_at FROM schema_migrations ORDER BY version DESC LIMIT 10'
    );
    res.json({
      tenantId,
      migrations: rows,
      poolStats: {
        totalCount: pool.totalCount,
        idleCount: pool.idleCount,
        waitingCount: pool.waitingCount
      }
    });
  } catch (err) {
    res.status(500).json({ error: 'Schema status query failed' });
  }
});

app.listen(9107);
